SELECT l.*, e.emp_no, e.name AS employee_name, d.name AS dept_name, u.nickname AS approve_by_name
FROM hr_leave l
JOIN hr_employee e ON e.id = l.employee_id
LEFT JOIN sys_dept d ON d.id = l.dept_id
LEFT JOIN sys_user u ON u.id = l.approve_by


        (l.leave_no LIKE CONCAT('%', #{q.keyword}, '%') OR e.emp_no LIKE CONCAT('%', #{q.keyword}, '%')
         OR e.name LIKE CONCAT('%', #{q.keyword}, '%'))

    AND l.kind = #{q.kind}
    AND l.type = #{q.type}
    AND l.status = #{q.status}
    AND l.dept_id = #{q.deptId}
    AND l.start_time >= #{q.beginDate}
    AND l.start_time < #{q.endBefore}

ORDER BY l.id DESC

SELECT * FROM hr_leave
WHERE status = 'APPROVED' AND start_time < #{to} AND end_time > #{from}
  AND employee_id IN #{id}

SELECT COUNT(*) FROM hr_leave
WHERE employee_id = #{employeeId} AND kind = #{kind} AND status IN ('APPROVING', 'APPROVED')
  AND start_time < #{end} AND end_time > #{start}
  AND id <> #{excludeId}

SELECT COALESCE(SUM(hours), 0) FROM hr_leave
WHERE employee_id = #{employeeId} AND kind = 'LEAVE' AND type = #{type} AND status IN ('APPROVING', 'APPROVED')
  AND start_time >= #{from} AND start_time < #{to}
